 47	function useRunnerHealth() {
 48	  const [health, setHealth] = useState<{ connected: boolean | null; activeRunId?: string }>({ connected: null });
 49	  useEffect(() => {
 50	    const controller = new AbortController();
 51	    let timer: ReturnType<typeof setTimeout>;
 52	    const check = async () => {
 53	      try {
 54	        const data = await requestJson('/api/health', { signal: controller.signal });
 55	        if (!data || typeof data !== 'object' || !('status' in data) || data.status !== 'ok') throw new Error('Invalid health response');
 56	        if (!controller.signal.aborted) setHealth({ connected: true, activeRunId: 'activeRunId' in data && isRunId(data.activeRunId) ? data.activeRunId : undefined });
 57	      } catch { if (!controller.signal.aborted) setHealth({ connected: false }); }
 58	      if (!controller.signal.aborted) timer = setTimeout(check, 10000);
 59	    };
 60	    void check();
 61	    return () => { controller.abort(); clearTimeout(timer); };
 62	  }, []);
 63	  return health;
 64	}
